// Dữ liệu giả lập — thay bằng Postgres / Google Sheets / API thật
const catalog = [
  { sku: 'SP001', ten: 'Cà phê rang xay Arabica 500g', gia: 185000, tonKho: 42 },
  { sku: 'SP002', ten: 'Trà ô long Bảo Lộc 200g', gia: 120000, tonKho: 0 },
  { sku: 'SP003', ten: 'Mật ong rừng U Minh 1L', gia: 350000, tonKho: 15 },
  { sku: 'SP004', ten: 'Hạt điều rang muối Bình Phước 500g', gia: 210000, tonKho: 8 }
];

const norm = s => (s || '').toString().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/g, 'd');
const words = s => norm(s).split(/[^a-z0-9]+/).filter(Boolean);
const q = words($input.first().json.query);
// Ưu tiên sản phẩm chứa ĐỦ các từ trong query (so khớp nguyên từ), nếu không có thì chứa ít nhất 1 từ
const score = p => { const t = words(p.ten + ' ' + p.sku); return q.filter(w => t.includes(w)).length; };
const all = catalog.filter(p => score(p) === q.length && q.length > 0);
const found = all.length ? all : catalog.filter(p => score(p) > 0);

return [{
  json: {
    query: $input.first().json.query,
    count: found.length,
    results: found.map(p => ({ ...p, trangThai: p.tonKho > 0 ? 'còn hàng' : 'hết hàng' }))
  }
}];
